-- A correction reverses the current accounting edition AND posts its exact
-- replacement atomically. No temporarily restored processor funds,provider
-- operation,customer-credit release or destructive history rewrite.
CREATE TABLE public.provider_dispute_corrections(
 academy_id uuid NOT NULL,id uuid NOT NULL,posting_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),replacement_id uuid NOT NULL,posted_on date NOT NULL,source jsonb NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,posting_id,version),UNIQUE(academy_id,replacement_id),CHECK(id<>replacement_id AND id<>posting_id AND replacement_id<>posting_id),
 FOREIGN KEY(academy_id,posting_id) REFERENCES public.provider_dispute_postings(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),
 FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(academy_id,replacement_id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE public.provider_dispute_corrections ENABLE ROW LEVEL SECURITY;ALTER TABLE public.provider_dispute_corrections FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.provider_dispute_corrections USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER finance_book_write BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_corrections FOR EACH STATEMENT EXECUTE FUNCTION public.guard_finance_book_write();
GRANT SELECT,INSERT ON public.provider_dispute_corrections TO kavosh_runtime;
CREATE FUNCTION public.provider_dispute_correction_source(p_posting uuid,p_balance uuid,p_on date,p_processor uuid,p_disputed uuid,p_fee uuid,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql VOLATILE SET search_path=pg_catalog AS $$
DECLARE r record;last record;c record;prior jsonb;next jsonb;BEGIN
 SELECT * INTO r FROM public.provider_dispute_postings WHERE id=p_posting;IF r.id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO last FROM public.provider_dispute_corrections WHERE academy_id=r.academy_id AND posting_id=r.id AND(p_exclude IS NULL OR id<>p_exclude) ORDER BY version DESC LIMIT 1;
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=r.academy_id AND id=r.collection_id;
 prior=CASE WHEN last.id IS NULL THEN r.source ELSE last.source->'next' END;
 next=public.provider_dispute_source(r.collection_id,p_balance,p_on,p_processor,p_disputed,p_fee);
 IF next IS NULL OR next->>'bookedId' IS DISTINCT FROM r.id::text OR next->>'accountId' IS DISTINCT FROM r.account_id OR next->'livemode' IS DISTINCT FROM to_jsonb(r.livemode) OR next->>'balanceTransactionId' IS DISTINCT FROM r.transaction_id OR next->>'disputeId' IS DISTINCT FROM r.dispute_id OR next->'manualReferenceExists' IS DISTINCT FROM 'false'::jsonb
 OR p_on<coalesce(last.posted_on,r.posted_on) OR next->'lines'=prior->'lines' THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('postingId',r.id,'collectionId',r.collection_id,'hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id,'collectorId',c.collector_id,'holdingAccountId',c.holding_account,'creditAccountId',c.credit_account,'version',coalesce(last.version,0),'previousJournalId',coalesce(last.replacement_id,r.id),'prior',prior,'next',next,'postedOn',p_on::text);
END $$;
CREATE FUNCTION public.guard_provider_dispute_correction() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r record;c record;p record;s jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT * INTO r FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=NEW.posting_id;SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=r.collection_id;
 PERFORM public.lock_customer_credit(c.id);PERFORM public.lock_collector_funds(c.collector_id,a.id) FROM(SELECT DISTINCT id FROM unnest(ARRAY[c.holding_account,(NEW.source#>>'{prior,processorAccountId}')::uuid,(NEW.source#>>'{next,processorAccountId}')::uuid]) id ORDER BY id) a;
 PERFORM id FROM public.tuition_invoices WHERE academy_id=NEW.academy_id AND id=c.invoice_id FOR UPDATE;PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':checkout-provider:'||c.account_id,0));
 IF NOT pg_try_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':provider-dispute:'||r.transaction_id,0)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_REFERENCE_BUSY' USING ERRCODE='40001';END IF;
 s=public.provider_dispute_correction_source(NEW.posting_id,(NEW.source#>>'{next,balanceInspectionId}')::uuid,NEW.posted_on,(NEW.source#>>'{next,processorAccountId}')::uuid,(NEW.source#>>'{next,disputedAccountId}')::uuid,(NEW.source#>>'{next,feeAccountId}')::uuid);
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF s IS NULL OR s IS DISTINCT FROM NEW.source OR NEW.version IS DISTINCT FROM(s->>'version')::integer+1 OR NEW.replacement_id=(s->>'previousJournalId')::uuid
 OR p.id IS NULL OR p.action IS DISTINCT FROM 'finance.provider-dispute.correct' OR p.status IS DISTINCT FROM 'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version<>0 OR p.privacy_capability IS DISTINCT FROM 'receipts.edit' OR p.review_context->'source' IS DISTINCT FROM s
 OR p.payload IS DISTINCT FROM jsonb_build_object('postingId',NEW.posting_id,'collectionId',c.id,'expectedVersion',NEW.version-1,'balanceInspectionId',s#>'{next,balanceInspectionId}','processorAccount',jsonb_build_object('id',s#>'{next,processorAccountId}','version',s#>'{next,processorVersion}'),'disputedFundsAccount',jsonb_build_object('id',s#>'{next,disputedAccountId}','version',s#>'{next,disputedVersion}'),'feeAccount',CASE WHEN s#>>'{next,feeAccountId}' IS NULL THEN 'null'::jsonb ELSE jsonb_build_object('id',s#>'{next,feeAccountId}','version',s#>'{next,feeVersion}') END,'feeTaxTreatment',s#>'{next,feeTaxTreatment}','postedOn',NEW.posted_on::text,'period',p.payload->'period','reason',NEW.reason)
 OR p.scope->'recordContext' IS DISTINCT FROM jsonb_build_object('hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id) OR NOT public.report_comment_human_verified(NEW.created_by) OR NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND status='active') THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_SOURCE_INVALID' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) AND(p.requester_id=NEW.created_by OR c.student_id=NEW.created_by OR EXISTS(SELECT 1 FROM public.family_relationships WHERE academy_id=NEW.academy_id AND student_id=c.student_id AND guardian_id=NEW.created_by) OR EXISTS(SELECT 1 FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id AND person_id=NEW.created_by)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_UPPER_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_correction BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_corrections FOR EACH ROW EXECUTE FUNCTION public.guard_provider_dispute_correction();
CREATE FUNCTION public.complete_provider_dispute_correction() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;j record;s jsonb;actual jsonb;expected jsonb;which integer;BEGIN
 s=public.provider_dispute_correction_source(NEW.posting_id,(NEW.source#>>'{next,balanceInspectionId}')::uuid,NEW.posted_on,(NEW.source#>>'{next,processorAccountId}')::uuid,(NEW.source#>>'{next,disputedAccountId}')::uuid,(NEW.source#>>'{next,feeAccountId}')::uuid,NEW.id);
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF s IS DISTINCT FROM NEW.source OR p.status IS DISTINCT FROM 'applied' OR p.reviewer_id IS DISTINCT FROM NEW.created_by THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_INCOMPLETE' USING ERRCODE='23514';END IF;
 FOR which IN 0..1 LOOP
  SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=CASE WHEN which=0 THEN NEW.id ELSE NEW.replacement_id END;
  IF which=0 THEN SELECT jsonb_agg(value||jsonb_build_object('side',CASE WHEN value->>'side'='debit' THEN 'credit' ELSE 'debit' END) ORDER BY n) INTO expected FROM jsonb_array_elements(NEW.source#>'{prior,lines}') WITH ORDINALITY l(value,n);ELSE expected=NEW.source#>'{next,lines}';END IF;
  SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',account_version,'side',side,'amountMinor',trunc(amount_minor)::text) ORDER BY line_number) INTO actual FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=j.id;
  IF j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.purpose IS DISTINCT FROM 'activity' OR j.period_id IS DISTINCT FROM(p.payload#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(p.payload#>>'{period,version}')::integer OR j.reverses_id IS DISTINCT FROM (CASE WHEN which=0 THEN(NEW.source->>'previousJournalId')::uuid ELSE NULL::uuid END) OR j.reference IS DISTINCT FROM (CASE WHEN which=0 THEN 'provider-dispute-correction:' ELSE 'provider-dispute-replacement:' END||NEW.id::text) OR actual IS DISTINCT FROM expected OR j.line_count<>jsonb_array_length(expected) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_JOURNALS_INVALID' USING ERRCODE='23514';END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM public.audit_events WHERE academy_id=NEW.academy_id AND entity_id=NEW.id AND actor_id=NEW.created_by AND created_at=transaction_timestamp() AND action='finance.provider-dispute.corrected' AND changes=jsonb_build_object('approvalId',NEW.approval_id,'postingId',NEW.posting_id,'version',NEW.version,'severity','critical','providerOperationPerformed',false,'creditRestored',false)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_AUDIT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_correction_complete AFTER INSERT ON public.provider_dispute_corrections DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.complete_provider_dispute_correction();
CREATE FUNCTION public.provider_dispute_correction_effect() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND NEW.action='finance.provider-dispute.correct' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_corrections WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_correction_effect AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_correction_effect();
CREATE FUNCTION public.provider_dispute_correction_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r record;c record;prior jsonb;hubs uuid[];ch uuid;BEGIN
 SELECT * INTO r FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'postingId')::uuid;SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=r.collection_id;
 SELECT source->'next' INTO prior FROM public.provider_dispute_corrections WHERE academy_id=NEW.academy_id AND posting_id=r.id ORDER BY version DESC LIMIT 1;prior=coalesce(prior,r.source);
 NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','receipts.view','scope',NEW.scope),jsonb_build_object('capability','checkouts.view','scope',NEW.scope),jsonb_build_object('capability','invoices.view','scope',NEW.scope));
 IF prior->>'feeAccountId' IS NOT NULL OR NEW.payload->'feeAccount'<>'null'::jsonb THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','expenses.view','scope',NEW.scope));END IF;
 SELECT array_agg(hub_id ORDER BY id) INTO hubs FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id=ANY(ARRAY[c.credit_account,c.holding_account,(r.source->>'processorAccountId')::uuid,(r.source->>'disputedAccountId')::uuid,(r.source->>'feeAccountId')::uuid,(prior->>'processorAccountId')::uuid,(prior->>'disputedAccountId')::uuid,(prior->>'feeAccountId')::uuid,(NEW.payload#>>'{processorAccount,id}')::uuid,(NEW.payload#>>'{disputedFundsAccount,id}')::uuid,(NEW.payload#>>'{feeAccount,id}')::uuid]);SELECT hub_id INTO ch FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id;
 NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(public.approval_hub_binding('accounts.view',hubs),public.approval_hub_binding('journals.view',hubs),public.approval_hub_binding('collectors.view',ARRAY[ch]));RETURN NEW;
END $$;
CREATE TRIGGER zz_provider_dispute_correction_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='finance.provider-dispute.correct') EXECUTE FUNCTION public.provider_dispute_correction_privacy();
DO $$ DECLARE body text;old text;BEGIN
 body=pg_get_functiondef('public.provider_dispute_journal_guard()'::regprocedure);
 old='IF NEW.reverses_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) THEN';
 IF strpos(body,old)=0 THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_GUARD_CHANGED';END IF;
 body=replace(body,old,'IF NEW.reverses_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) OR EXISTS(SELECT 1 FROM public.provider_dispute_corrections WHERE academy_id=NEW.academy_id AND replacement_id=NEW.reverses_id)) AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_corrections WHERE academy_id=NEW.academy_id AND id=NEW.id AND approval_id=NEW.approval_id AND source->>''previousJournalId''=NEW.reverses_id::text) THEN');
 old='IF canonical~';
 IF strpos(body,old)=0 THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_CORRECTION_REFERENCE_CHANGED';END IF;
 EXECUTE replace(body,old,'IF (canonical LIKE ''provider-dispute-correction:%'' OR canonical LIKE ''provider-dispute-replacement:%'') AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_corrections WHERE academy_id=NEW.academy_id AND approval_id=NEW.approval_id AND((id=NEW.id AND canonical=''provider-dispute-correction:''||id::text) OR(replacement_id=NEW.id AND canonical=''provider-dispute-replacement:''||id::text))) THEN RAISE EXCEPTION ''PROVIDER_DISPUTE_CORRECTION_SOURCE_REQUIRED'' USING ERRCODE=''23514'';END IF; IF canonical~');
END $$;
DO $$ DECLARE body text;BEGIN body=pg_get_viewdef('public.collector_fund_events'::regclass,true);EXECUTE 'CREATE OR REPLACE VIEW public.collector_fund_events WITH(security_invoker=true) AS '||rtrim(body,E';\n ')||' UNION ALL SELECT x.academy_id,c.collector_id,(x.source#>>''{prior,processorAccountId}'')::uuid,x.id,x.posted_on,-(x.source#>>''{prior,netMinor}'')::numeric FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id JOIN public.provider_collections c ON c.academy_id=d.academy_id AND c.id=d.collection_id UNION ALL SELECT x.academy_id,c.collector_id,(x.source#>>''{next,processorAccountId}'')::uuid,x.replacement_id,x.posted_on,(x.source#>>''{next,netMinor}'')::numeric FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id JOIN public.provider_collections c ON c.academy_id=d.academy_id AND c.id=d.collection_id';END $$;
CREATE VIEW public.provider_cost_events WITH(security_invoker=true) AS
 SELECT d.academy_id,d.id,d.collection_id,d.approval_id,d.posted_on,d.fee_minor,d.source FROM public.provider_dispute_postings d
 UNION ALL SELECT x.academy_id,x.id,d.collection_id,x.approval_id,x.posted_on,-(x.source#>>'{prior,feeMinor}')::numeric,x.source->'prior' FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id
 UNION ALL SELECT x.academy_id,x.replacement_id,d.collection_id,x.approval_id,x.posted_on,(x.source#>>'{next,feeMinor}')::numeric,x.source->'next' FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id;
GRANT SELECT ON public.provider_cost_events TO kavosh_runtime;
REVOKE ALL ON FUNCTION public.provider_dispute_correction_source(uuid,uuid,date,uuid,uuid,uuid,uuid),public.guard_provider_dispute_correction(),public.complete_provider_dispute_correction(),public.provider_dispute_correction_effect(),public.provider_dispute_correction_privacy() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_correction_source(uuid,uuid,date,uuid,uuid,uuid,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 332 $$;
